/* ==================================================
   SET COLOR THEME
================================================== */

const randomTheme =
  colorThemes[Math.floor(Math.random() * colorThemes.length)];

document.documentElement.style.setProperty(
  "--bg-color",
  randomTheme.background
);

document.documentElement.style.setProperty(
  "--text-color",
  randomTheme.text
);





/* ==================================================
   SET CHINESE SYMBOLS
================================================== */

const cnSymbols = [
  "——",
  "……"
];

function wrapCnSymbolsInString(text) {
  if (!text) return "";
  let result = text;
  cnSymbols.forEach(symbol => {
    result = result
      .split(symbol)
      .join(`<span class="cn">${symbol}</span>`);
  });
  return result;
}







/* ==================================================
   写入 INTRO CONTENT
================================================== */

const scrollDistance = parseFloat(
  getComputedStyle(document.documentElement).getPropertyValue("--paddings-3x")
);

const intro = document.querySelector(".intro");
const introTextMobile = document.querySelector(".intro-mobile");
const introTextCn = document.querySelector(".intro-cn");
const introTextEn = document.querySelector(".intro-en");
const introTextMeta = document.querySelector(".intro-meta");

const collapsedSeparator = "&emsp;&emsp;";

// 中文Intro
function createIntroCnParagraphs(paragraphs) {
  if (!Array.isArray(paragraphs)) {
    return "";
  }
  return paragraphs
    .map(text => `<p>${wrapCnSymbolsInString(text)}</p>`)
    .join("");
}

// 英文Intro
function createIntroEnParagraphs(paragraphs) {
  if (!Array.isArray(paragraphs)) {
    return "";
  }
  return paragraphs
    .map(text => `<p>${text}</p>`)
    .join("");
}

// collapsed内容
function createCollapsedText(items) {
  if (!Array.isArray(items)) {
    return "";
  }
  return items.join(collapsedSeparator);
}

// Meta信息
function createIntroMeta(collapsed = false) {
  const socialLinks = introContent.meta.social
    .map(item => `<a href="${item.url}" target="_blank">${item.text}</a>`)
    .join(", ");
  const contactLink = `
    <a href="${introContent.meta.contact.url}">
      ${introContent.meta.contact.text}
    </a>
  `;
  if (collapsed) {
    return `
      <p>${socialLinks}</p>
      <p>${contactLink}</p>
    `;
  }
  return `
    <p>After Pity on:<br>${socialLinks}</p>
    <p>Touch:<br>${contactLink}</p>
  `;
}

// INITIAL RENDER
function initIntroContent() {
  if (!intro) return;
  // DESKTOP 中文
  if (introTextCn) {
    introTextCn.innerHTML = `
      <div class="intro-state intro-full">
        ${createIntroCnParagraphs(introContent.cn.full)}
      </div>
      <div class="intro-state intro-collapsed">
        <p>
          ${wrapCnSymbolsInString(createCollapsedText(introContent.cn.collapsed))}
        </p>
      </div>
    `;
  }
  // DESKTOP 英文
  if (introTextEn) {
    introTextEn.innerHTML = `
      <div class="intro-state intro-full">
        ${createIntroEnParagraphs(introContent.en.full)}
      </div>
      <div class="intro-state intro-collapsed">
        <p>
          ${createCollapsedText(introContent.en.collapsed)}
        </p>
      </div>
    `;
  }
  // META
  if (introTextMeta) {
    introTextMeta.innerHTML = `
      <div class="intro-state intro-full">
        ${createIntroMeta(false)}
      </div>
      <div class="intro-state intro-collapsed">
        ${createIntroMeta(true)}
      </div>
    `;
  }
  // MOBILE
  if (introTextMobile) {
    introTextMobile.innerHTML = `
      <div class="intro-state intro-full">
        <div class="mobile-intro-default">
          ${createIntroCnParagraphs(introContent.cn.mobile)}
          ${createIntroCnParagraphs(introContent.en.mobile)}
          <p><a href="#" class="more-button" data-action="expand" >更多 More</a></p>
        </div>
        <div class="mobile-intro-expanded">
          ${createIntroCnParagraphs(introContent.cn.full)}
          ${createIntroEnParagraphs(introContent.en.full)}
          <p><a href="#" class="more-button" data-action="collapse">收起 Less</a></p>
        </div>
      </div>
      <div class="intro-state intro-collapsed">
        <p><a href="${homepageURL}">After Pity</a></p>
      </div>
    `;
  }
}

// MORE / LESS TOGGLE
if (introTextMobile) {
  introTextMobile.addEventListener("click", event => {
    const button = event.target.closest(".more-button");
    if (!button) return;
    event.preventDefault();
    intro.classList.toggle("mobile-expanded", button.dataset.action === "expand");
  });
}

// SCROLL
let introCollapsed = false;
window.addEventListener("scroll", () => {
  const shouldCollapse = window.scrollY > scrollDistance;
  if (shouldCollapse === introCollapsed) {
    return;
  }
  introCollapsed = shouldCollapse;
  intro.classList.toggle("is-collapsed", introCollapsed);
});

//  INIT INTRO
function initIntro() {
  initIntroContent();
}
initIntro();










/* ==================================================
   SHOW WORK COVER WHEN HEADLINE HOVERED
================================================== */
  
const headlines = document.querySelectorAll(".headline");
const imageCursor = document.querySelector(".image-cursor");
const canHover = window.matchMedia("(hover: hover) and (pointer: fine)").matches;

if (canHover && imageCursor) {
  headlines.forEach((item) => {
    item.addEventListener("mouseenter", () => {
      imageCursor.src = item.dataset.cursor;
      imageCursor.style.opacity = "1";
      imageCursor.style.visibility = "visible";
    });
    item.addEventListener("mousemove", (event) => {
      imageCursor.style.left = `${event.clientX}px`;
      imageCursor.style.top = `${event.clientY}px`;
    });
    item.addEventListener("mouseleave", () => {
      imageCursor.style.opacity = "0";
      imageCursor.style.visibility = "hidden";
    });
  });
} else {
  headlines.forEach(item => {
    const imageSrc = item.dataset.cursor;
    const headlineEn = item.querySelector(".headline-en");
    if (!imageSrc || !headlineEn) return;

    const hasComma = /,&nbsp;\s*$/.test(headlineEn.innerHTML); // 判断原标题最后是否有逗号
    if (hasComma) {
      headlineEn.innerHTML = headlineEn.innerHTML.replace(/,&nbsp;\s*$/, "&nbsp;");
    }

    const img = document.createElement("img");
    img.className = "mobile-cover";
    img.src = imageSrc;
    img.alt = "";
    item.appendChild(img);

    if (hasComma) {
      const punctuation = document.createElement("span");
      punctuation.className = "headline-en mobile-cover-punctuation";
      punctuation.innerHTML = ",&nbsp;";
      item.appendChild(punctuation);
    }
  });
}





/* ==================================================
   写入 WORK INFO
================================================== */

const workTitle = document.getElementById("work-title");
const authorName = document.getElementById("author-name");
const authorIntro = document.getElementById("author-intro");
const workYear = document.getElementById("work-year");
const workMaterial = document.getElementById("work-material");
const workSize = document.getElementById("work-size");
const workEdition = document.getElementById("work-edition");
const workBody = document.getElementById("work-body");


// 普通文本
function setText(element, value) {
  if (!element) return;
  element.textContent = value ?? "";
}

// 多行文本
function setMultilineText(element, value) {
  if (!element) return;
  if (!value) {
    element.innerHTML = "";
    return;
  }
  if (Array.isArray(value)) {
    element.innerHTML = value.join("<br>");
  } else {
    element.textContent = value;
  }
}

// 正文段落
function renderParagraphSection(classNames, paragraphs, wrapCnSymbols = false) {

  if (!Array.isArray(paragraphs) || paragraphs.length === 0) {
    return;
  }

  const section = document.createElement("section");
  section.className = classNames;

  paragraphs.forEach(text => {
    const p = document.createElement("p");
    p.innerHTML = wrapCnSymbols
      ? wrapCnSymbolsInString(text)
      : text;
    section.appendChild(p);
  });

  workBody.appendChild(section);

}


// 媒体
function renderMedia(data) {
  if (
    !Array.isArray(data.media) || data.media.length === 0
  ) {
    return;
  }

  data.media.forEach(item => {
    const figure = document.createElement("figure");
    figure.className = "image";

    if (item.type === "image") {
      const img = document.createElement("img");
      img.src = data.mediaBase + item.file;
      img.alt = item.alt ?? "";
      figure.appendChild(img);
    }
    else if (item.type === "video") {
      const video = document.createElement("video");
      video.src = data.mediaBase + item.file;
      video.controls = item.controls ?? true;
      video.muted = item.muted ?? false;
      video.autoplay = item.autoplay ?? false;
      video.loop = item.loop ?? false;
      video.playsInline = true;
      figure.appendChild(video);
    }

    workBody.appendChild(figure);
  });
}


function initWorkPage() {
  if (typeof workData === "undefined") {
    return;
  }

  document.title = workData.page_title ?? "";
  setText(workTitle, workData.work_title);
  setText(authorName, workData.author_name);
  setMultilineText(authorIntro, workData.author_intro);
  setText(workYear, workData.work_year);
  setMultilineText(workMaterial, workData.work_material);
  setMultilineText(workSize, workData.work_size);
  setMultilineText(workEdition, workData.work_edition);

  workBody.innerHTML = "";
  renderParagraphSection("article article-cn", workData.work_intro_cn, true);
  renderParagraphSection("article article-en", workData.work_intro_en, false);
  renderMedia(workData);
}

initWorkPage();

const workMeta = document.querySelector(".work-meta");
const workLabel = document.querySelector(".work-label");
if (workMeta && workLabel) {
  workLabel.addEventListener("click", () => {
    workMeta.classList.toggle("is-open");
  });
}






